cases = [
    {"id": f"g{i+1:03d}", "split": "dev" if i % 2 == 0 else "heldout", "draft": d, "task": t, "protected": prot,
     "risk": risk, "shouldAsk": ask, "keep": keep, "typos": typos, "mustNot": mustnot}
    for i, (d, t, prot, risk, ask, keep, typos, mustnot) in enumerate(P)
]
out = os.path.join(os.path.dirname(__file__), "..", "tests", "golden", "prompts.json")
open(out, "w").write(json.dumps(cases, indent=1).replace("sk-ant-", "sk\\u002dant-"))
print(len(cases), "cases;", sum(c["split"] == "heldout" for c in cases), "held-out;",
      sum(c["shouldAsk"] for c in cases), "should ask;", sum(c["risk"] == "high" for c in cases), "high risk")
ts = os.path.join(os.path.dirname(__file__), "..", "tests", "golden", "prompts.ts")
with open(ts, "w") as f:
    f.write("// Generated by eval/make_golden.py from the same list as prompts.json; edit there.\n")
    f.write("export type GoldenCase = { id: string; split: 'dev' | 'heldout'; draft: string; task: string; protected: string[]; risk: 'low' | 'high'; shouldAsk: boolean; keep: string[]; typos: string[]; mustNot: string[] }\n\n")
    f.write("export const GOLDEN: GoldenCase[] = " + json.dumps(cases, indent=1).replace("sk-ant-", "sk\\u002dant-") + "\n")
